(function () {
    cc.XXInviteUserView = cc.Class({
        "extends": cc.PopupBase,
        properties: {
            inviteUserListView: cc.XXInviteUserListView,
        },

        onLoad: function () {
            this.animation = this.node.getComponent(cc.Animation);
            this.node.zIndex = cc.NoteDepth.POPUP_TAIXIU;
        },

        onEnable: function () {
            var self = this;
            var delay = 0.2;
            cc.director.getScheduler().schedule(function () {
                self.getGroupUser();
            }, this, 1, 0, delay, false);

            this.animation.play('openPopupXd');
        },

        getGroupUser: function () {
            var getGroupUserCommand = new cc.XXGroupUserCommand;
            getGroupUserCommand.execute(this);
        },

        onGetGroupUserResponse: function (response) {
            var list = response;
            //var list = slotsHistoryListData;
            if (list !== null && list.length > 0) {
                this.inviteUserListView.resetList();
                this.inviteUserListView.initialize(list);
            }
        },

        closeClicked: function () {
            this.inviteUserListView.resetList();
            this.animation.play('closePopupXd');
            var self = this;
            var delay = 0.12;
            cc.director.getScheduler().schedule(function () {
                self.animation.stop();
                cc.XXPopupController.getInstance().destroyInviteUserView();
            }, this, 1, 0, delay, false);
        },
    });
}).call(this);